window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a74640e77375b5c0"]={"versions": [{"id": "FIG-a74640e77375b5c0", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Statisches AUTOSAR-Architektur- und Schichtenmodell (Blockschaltbild / BSW-Integrationsarchitektur).</li>\n<li><strong>Funktionale Einordnung:</strong> Detaillierung der Einbettung des BSW-Moduls <strong>XCP</strong> (<em>Universal Measurement and Calibration Protocol</em>) in die AUTOSAR Classic Platform (Services Layer) sowie dessen Schnittstellen zu Nachbarmodulen (OS, RTE, Bus-Interfaces).</li>\n<li><strong>Technischer Zweck:</strong> Visualisierung der Entkopplung zwischen busunabhängigem Kernprotokoll (<strong>XCP Protocol</strong>) und den busspezifischen Transportschichten (<strong>XCPonCan</strong>, <strong>XCPonFr</strong>, <strong>XCPonEth</strong> via <strong>SoAd</strong>), unter Umgehung des standardmäßigen PDU-Routers (<strong>PduR</strong>) direkt auf die Kommunikations-Hardware-Abstraktionsschicht (<strong>Bus Interface(s)</strong>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten und Module</p>\n<ul class=\"fig-list\">\n<li><strong>Application / Runtime Environment (RTE):</strong></li>\n<li>Oberste Abstraktionsschicht; interagiert bidirektional mit <strong>COM</strong> (Standard-Signal-/PDU-Pfad) sowie potenziell mit XCP über Mess-/Kalibrierdatenpunkte (DAQs/STIMs via RTE-Bypass/Events).</li>\n<li><strong>Services Layer (BSW):</strong></li>\n<li><strong>OS (Operating System):</strong> Direkte Kopplung zum XCP-Kern (orangefarbener Doppelpfeil) für Task-Scheduling, Timer, Interrupt-Sperren (<code>SchM</code>/Resource Protection) und zyklische Event-Trigger (<code>Xcp_EventChannel</code>).</li>\n<li><strong>XCP-Modul (abgegrenzter Hauptblock):</strong></li>\n<li><em>XCP Protocol:</em> Protokollzustandsmaschine, DAQ-/STIM-Listenverarbeitung, Page-Handling, Seed&Key, Checksummen- und Memory-Proxy-Operationen.</li>\n<li><em>XCPonCan:</em> Transportschicht für CAN/CAN-FD; bindet direkt an <code>CanIf</code> an.</li>\n<li><em>XCPonFr:</em> Transportschicht für FlexRay; bindet direkt an <code>FrIf</code> an (inkl. Synchronisations- und PDU-Aggregation).</li>\n<li><em>XCPonEth:</em> Transportschicht für Ethernet (TCP/UDP); nutzt direkt den <strong>SoAd</strong> (<em>Socket Adaptor</em>) innerhalb des Modul-Stacks.</li>\n<li><strong>Standard-Kommunikationsstack (Vergleichs- und Koexistenzpfad):</strong></li>\n<li><strong>IPDUM:</strong> Multiplexing/Demultiplexing von I-PDUs, angebunden an PduR.</li>\n<li><strong>COM:</strong> Standard-Signal-PDU-Verarbeitung, Schnittstelle zur RTE.</li>\n<li><strong>DCM:</strong> Diagnosesteuerung; bindet an PduR an (UDS-Pfad).</li>\n<li><strong>PDUR (PDU Router):</strong> Zentraler Routing-Knoten für Normal- und Diagnosekommunikation. <em>XCP umgeht den PduR vollständig</em> und routet PDUs nicht über PduR-Routing-Tabellen.</li>\n<li><strong>TP:</strong> Transportprotokolle (z. B. <code>CanTp</code>, <code>FrTp</code>) unterhalb des PduR.</li>\n<li><strong>NM:</strong> Network Management, direkt an Bus-Interfaces angebunden.</li>\n<li><strong>Communication HW Abstraction (Green Layer):</strong></li>\n<li><strong>Bus Interface(s):</strong> Generische Repräsentation von <code>CanIf</code>, <code>FrIf</code>, <code>EthIf</code> (bzw. SoAd/EthIf-Kette). Empfängt und sendet PDUs über standardisierte Interface-APIs (z. B. <code>CanIf_Transmit</code>, <code>CanIf_RxIndication</code>, <code>CanIf_TxConfirmation</code>).</li>\n<li><strong>Communication Drivers (Red Layer):</strong></li>\n<li><strong>Bus Driver(s):</strong> Hardwarenahe Controller-Treiber (<code>Can</code>, <code>Fr</code>, <code>Eth</code>), die Register und Mailboxen der Transceiver/Controller bedienen.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellenbeziehungen und Kopplungen</p>\n<ul class=\"fig-list\">\n<li><strong>XCPonCan $\\leftrightarrow$ Bus Interface(s):</strong> Asynchrone PDU-Schnittstelle (<code>CanIf</code>).</li>\n<li><strong>XCPonFr $\\leftrightarrow$ Bus Interface(s):</strong> Zwei Pfade: Standard-PDU-Transfer (schwarz) sowie zeitkritische FlexRay-Trigger-/Synchronisations-Schnittstelle (orange/gelb, z. B. <code>FrIf_Transmit</code> mit <code>FrIf_GetGlobalTime</code> / <code>TriggerTransmit</code>).</li>\n<li><strong>XCPonEth / SoAd $\\leftrightarrow$ Bus Interface(s):</strong> Socket-basierte PDU-Schnittstelle (<code>SoAd_IfTransmit</code>, <code>SoAd_IfRoutingGroupCopyRxData</code>).</li>\n<li><strong>PduR-Bypass:</strong> Keine Verbindungslinie zwischen XCP und PduR; XCP implementiert seine eigene Transportschicht-Logik direkt auf Interface-Ebene.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Verbindungsaufbau:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach BSW-Init (<code>EcuM</code>/<code>BswM</code>) wartet XCP im Status <code>DISCONNECTED</code>.</li>\n<li>Empfang eines <code>CONNECT</code>-CTO via <code>*If_RxIndication()</code> setzt die interne Session auf <code>CONNECTED</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kommando-Verarbeitung (CTO / CRM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchroner/Asynchroner Pfad: XCP-Master sendet CTO (Command Transfer Object) via Bus-Interface $\\rightarrow$ <code>Xcp_&lt;Transport&gt;RxIndication()</code>.</li>\n<li>XCP verarbeitet das Kommando im Main-Function-Zyklus oder direkt im ISR-Kontext (abhängig von der Konfiguration) und sendet CRM (Command Response Message) via <code>*If_Transmit()</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Messdaten-Erfassung (DAQ - Synchroner Pfad zum OS):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>OS-Task oder Timer triggert <code>Xcp_EventChannel(EventChannelId)</code>.</li>\n<li>XCP Protocol liest konfigurierte RAM-Adressen konsistent (ggf. unter OS-Interruptsperre / SuspendOSInterrupts).</li>\n<li>Generierte DTOs (Data Transfer Objects) werden an die entsprechende Transportschicht (<code>XCPonCan</code>, <code>XCPonFr</code>, <code>XCPonEth</code>) übergeben und an das Bus-Interface dispatcht.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kalibrierung / Stimulation (STIM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>DTO-Empfang via Bus-Interface puffert Daten in STIM-Buffers; Freigabe in das Applikations-RAM synchron zum konfigurierten <code>Xcp_EventChannel</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Tx-Bestätigung & Flow Control:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Quittierung durch Bus-Interface über <code>Xcp_&lt;Transport&gt;TxConfirmation()</code>. Erst nach TxConfirmation darf die nächste CTO/DTO-Mailbox freigegeben werden (abhängig von PDU-Buffer-Tiefe).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PduR-Bypass & PDU-Konfiguration (SWS_Xcp_00701, SWS_Xcp_00702):</strong></li>\n<li>Da XCP nicht über den PduR geroutet wird, müssen XCP-PDUs direkt in den Interfaces (<code>CanIf</code>, <code>FrIf</code>, <code>SoAd</code>) als Dedicated- oder TriggerTransmit-PDUs konfiguriert werden. Upper Layer ist hierbei direkt <code>XCP</code>.</li>\n<li><strong>FlexRay-Spezifika (SWS_Xcp_00703, SWS_Xcp_00705):</strong></li>\n<li><code>XCPonFr</code> erfordert Synchronisation mit dem FlexRay-Zyklus (<code>FrIf_GetGlobalTime</code>). Das Zusammenspiel aus PDU-Pufferung und Ausführungszeitpunkten im Dynamic/Static Segment muss präzise auf die Schedule-Tabelle des Clusters abgestimmt sein.</li>\n<li><strong>Ethernet-Anbindung via SoAd (SWS_Xcp_00706, SWS_Xcp_00707):</strong></li>\n<li><code>XCPonEth</code> bindet normativ an die Schnittstellen des <code>SoAd</code> (Socket Adaptor). Der Stack benötigt konfigurierte SoAd-PDU-Routen und Socket-Connections (TCP oder UDP Port 5555 default).</li>\n<li><strong>OS-Integration & Task-Mapping (SRS_Xcp_29009, SRS_Xcp_29010):</strong></li>\n<li>Hohe Rechenlast durch <code>Xcp_EventChannel()</code> bei schnellen Abtastraten (z. B. 1 ms). Entwickler müssen sicherstellen, dass XCP-Events in prioritätsgerechten OS-Tasks oder Rte-Bypass-Events aufgerufen werden, ohne die Safety-relevanten Applikationstasks zu preemptieren.</li>\n<li><strong>Exklusivbereiche & Reentrancy:</strong></li>\n<li>SchM-Locks (<code>XCP_EXCLUSIVE_AREA_*</code>) sichern den Zugriff auf DAQ-Puffer und ODT-Einträge bei simultanem Zugriff durch OS-Tasks unterschiedlicher Priorität ab.</li>\n</ul>"}, {"id": "FIG-59d7945c7cfa1bd4", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Statisches AUTOSAR-Architektur- und Schichtenmodell (Blockschaltbild / BSW-Integrationsarchitektur).</li>\n<li><strong>Funktionale Einordnung:</strong> Einbettung des BSW-Moduls <strong>XCP</strong> (<em>Universal Measurement and Calibration Protocol</em>) in die AUTOSAR Classic Platform (Services Layer) sowie dessen Schnittstellen zum <strong>PDU Router</strong> und direkt zur Kommunikations-Hardware-Abstraktionsschicht (<strong>Bus Interface(s)</strong>).</li>\n<li><strong>Technischer Zweck:</strong> Visualisierung des dualen Kommunikationspfads für XCP (<code>XCPonFr / XCPonCAN / XCPonTCP/IP / Interfaces</code>): Einerseits die reguläre I-PDU-Anbindung an den zentralen <strong>PDU Router</strong>, andererseits ein direkter Bypass-Pfad (orange) an die <strong>Bus Interface(s)</strong> unter Umgehung von PDU Router und <strong>L-SDU Router</strong>, eingebettet in die Gesamthierarchie aus RTE, Services Layer, Communication HW Abstraction und Communication Drivers.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten und Module</p>\n<ul class=\"fig-list\">\n<li><strong>Application / Runtime Environment (RTE):</strong></li>\n<li>Oberste Abstraktionsschicht; tauscht Signale (<code>Signals</code>) bidirektional mit <strong>AUTOSAR COM</strong> aus.</li>\n<li><strong>Services Layer (BSW):</strong></li>\n<li><strong>XCP Protocol:</strong> Enthält das XCP-Kernprotokoll sowie die Transportschnittstellen <code>XCPonFr / XCPonCAN / XCPonTCP/IP / Interfaces</code>.</li>\n<li><strong>PDU Router:</strong> Zentraler Routing-Knoten für I-PDUs.</li>\n<li><strong>Module oberhalb des PDU Routers:</strong></li>\n<li><strong>XCP Protocol:</strong> Bidirektional über <code>I-PDU</code> mit dem PDU Router verbunden.</li>\n<li><strong>IPDU Multiplexer:</strong> Bidirektional über <code>I-PDU</code> mit dem PDU Router verbunden.</li>\n<li><strong>AUTOSAR COM:</strong> Signal-Schnittstelle (<code>Signals</code>) zur RTE und bidirektionale <code>I-PDU</code>-Schnittstelle zum PDU Router.</li>\n<li><strong>Diagnostic Communication Manager (DCM):</strong> Bidirektional über <code>I-PDU</code> mit dem PDU Router verbunden.</li>\n<li><strong>Diagnostic Log and Trace (DLT):</strong> Bidirektional über <code>I-PDU</code> mit dem PDU Router verbunden.</li>\n<li><strong>Module unterhalb des PDU Routers:</strong></li>\n<li><strong>Socket Adpater / TcpIp:</strong> Kaskadierte Schichten unterhalb des PDU Routers; angebunden an den PDU Router und nach unten an den L-SDU Router.</li>\n<li><strong>AUTOSAR Tp:</strong> Transportprotokollschicht; über <code>I-PDU¹</code> an den PDU Router und über <code>N-PDU</code> an den L-SDU Router angebunden.</li>\n<li><strong>NM Module:</strong> Network Management Modul; über <code>N-PDU</code> an den L-SDU Router in der Communication HW Abstraction angebunden.</li>\n<li><strong>Communication HW Abstraction:</strong></li>\n<li><strong>L-SDU Router:</strong> Obere Teilkomponente der HW-Abstraktionsschicht; empfängt und sendet PDUs (<code>I-PDU</code>, <code>N-PDU</code>) von PDU Router, TcpIp, AUTOSAR Tp und NM Module.</li>\n<li><strong>Bus Interface(s):</strong> Untere Teilkomponente der HW-Abstraktionsschicht; generische Schnittstellen für Bus-Treiber.</li>\n<li><strong>Communication Drivers:</strong></li>\n<li><strong>Bus Driver(s):</strong> Hardwarenahe Treiber; über <code>L-PDU</code> bidirektional mit den <code>Bus Interface(s)</code> verbunden.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellenbeziehungen und Datenpfade</p>\n<ul class=\"fig-list\">\n<li><strong>XCP-PDU-Router-Pfad:</strong> Bidirektionaler PDU-Austausch zwischen XCP Protocol und PDU Router (<code>I-PDU</code>).</li>\n<li><strong>XCP-Bypass-Pfad (orange Verbindung):</strong> Direkte, dedizierte Schnittstelle vom XCP Protocol an die <code>Bus Interface(s)</code>, die den PDU Router, Socket Adapter / TcpIp und den L-SDU Router umgeht.</li>\n<li><strong>PDU-Hierarchie:</strong> <code>Signals</code> (RTE $\\leftrightarrow$ AUTOSAR COM) $\\rightarrow$ <code>I-PDU</code> (Services Layer Module $\\leftrightarrow$ PDU Router $\\leftrightarrow$ L-SDU Router / AUTOSAR Tp / Socket Adapter) $\\rightarrow$ <code>N-PDU</code> (AUTOSAR Tp / NM Module $\\leftrightarrow$ L-SDU Router) $\\rightarrow$ <code>L-PDU</code> (Bus Interface(s) $\\leftrightarrow$ Bus Driver(s)).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Verbindungsaufbau:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach dem Systemstart befindet sich das XCP-Protokoll im Zustand <code>DISCONNECTED</code>.</li>\n<li>Der Empfang eines Connect-Kommandos (über den PDU Router via <code>I-PDU</code> oder direkt über die Bus-Interfaces) etabliert die XCP-Kommunikationssitzung (<code>CONNECTED</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kommando- und Antwortabwicklung (CTO / CRM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der XCP-Master sendet CTOs (Command Transfer Objects) entweder über den standardisierten PDU-Router-Pfad (<code>I-PDU</code>) oder über den direkten Bypass-Pfad an das Bus-Interface.</li>\n<li>Das XCP Protocol verarbeitet Kommandos und sendet Command Response Messages (CRM) über denselben Pfad zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Messdaten- und Stimulationsdatenfluss (DAQ / STIM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für zeitkritische Messdatenübertragung (DAQ) und Stimulation (STIM) kann der direkte Pfad (orange Linie) zu den Bus-Interfaces genutzt werden, wodurch Verarbeitungs- und Routinglatenzen von PDU Router und L-SDU Router vermieden werden.</li>\n<li>Alternativ werden DAQ-/STIM-PDUs als I-PDUs über den PDU Router an die nachgelagerten Instanzen (<code>AUTOSAR Tp</code>, <code>Socket Adpater / TcpIp</code> oder direkt als I-PDU an den L-SDU Router) übertragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Segmentierung und Transportprotokolle:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Große Datenpakete werden über den PDU Router an <code>AUTOSAR Tp</code> übergeben, in <code>N-PDU</code> segmentiert und dem L-SDU Router zugeführt, bzw. über Socket Adapter / TcpIp abgewickelt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Buszugriff und Treiberinteraktion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der L-SDU Router und die Bus Interfaces leiten die Daten als Link-Layer-PDUs (<code>L-PDU</code>) bidirektional an die Bus Drivers weiter.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Duale XCP-Anbindung (PDU Router vs. Direct Interface):</strong></li>\n<li>XCP unterstützt sowohl die Integration über den <code>PDU Router</code> (mittels <code>I-PDU</code>) als auch die direkte Kopplung an die <code>Bus Interface(s)</code> (oranger Pfad). Die Modulkonfiguration legt fest, welche PDU-Typen und Event-Channels über den PduR geroutet werden und welche Kanäle direkt an das Bus-Interface angebunden sind.</li>\n<li><strong>L-SDU Router in der Hardware-Abstraktionsschicht:</strong></li>\n<li>Der <code>L-SDU Router</code> fungiert als Routing-Instanz innerhalb der Communication HW Abstraction zur Vermittlung zwischen Services Layer (PduR, Tp, TcpIp, NM) und den Bus-Interfaces.</li>\n<li><strong>Transportwege für XCPonTCP/IP:</strong></li>\n<li>Ethernet-basierte Kommunikation wird über die Kette <code>PDU Router</code> $\\rightarrow$ <code>Socket Adpater</code> [sic] $\\rightarrow$ <code>TcpIp</code> $\\rightarrow$ <code>L-SDU Router</code> bzw. über den direkten Pfad realisiert.</li>\n<li><strong>Koexistenz im Kommunikationsstack:</strong></li>\n<li>XCP teilt sich den PDU Router mit <code>IPDU Multiplexer</code>, <code>AUTOSAR COM</code>, <code>Diagnostic Communication Manager</code> und <code>Diagnostic Log and Trace (DLT)</code>. Entsprechende PDU-IDs und Routing-Pfade müssen kollisionsfrei konfiguriert werden.</li>\n<li><strong>PDU-Typisierung und Protokollschichten:</strong></li>\n<li>Die explizite Kennzeichnung der Schnittstellen (<code>Signals</code>, <code>I-PDU</code>, <code>I-PDU¹</code>, <code>N-PDU</code>, <code>L-PDU</code>) definiert die zulässigen Datenformate an den Modulgrenzen.</li>\n</ul>"}], "trans": [{"from": "FIG-a74640e77375b5c0", "to": "FIG-59d7945c7cfa1bd4", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>XCP Protocol:</strong> I-PDU-Schnittstellenverbindung direkt zum PDU Router ergänzt; interne Modulaufteilung durch <code>XCPonFr / XCPonCAN / XCPonTCP/IP / Interfaces</code> ersetzt; oranger Bypass-Pfad führt direkt an die <code>Bus Interface(s)</code>.</li>\n<li><strong>OS (Operating System):</strong> Modulblock und direkte Schnittstelle zum XCP Protocol entfernt.</li>\n<li><strong>Diagnostic Log and Trace (DLT):</strong> Als BSW-Modul im Services Layer ergänzt, bidirektional über <code>I-PDU</code> an den PDU Router angebunden.</li>\n<li><strong>PDU Router:</strong> Bindet XCP Protocol nun direkt über <code>I-PDU</code> ein; direkte I-PDU-Pfade zum L-SDU Router sowie Anbindungen an Socket Adapter und AUTOSAR Tp (<code>I-PDU¹</code>) ergänzt.</li>\n<li><strong>Communication HW Abstraction:</strong> Um den <code>L-SDU Router</code> oberhalb der <code>Bus Interface(s)</code> erweitert.</li>\n<li><strong>Socket Adapter & TcpIp:</strong> Als Protokollkette zwischen PDU Router und L-SDU Router eingefügt.</li>\n<li><strong>AUTOSAR Tp & NM Module:</strong> Schnittstellen zur Communication HW Abstraction als <code>N-PDU</code> typisiert; AUTOSAR Tp bindet über <code>I-PDU¹</code> an den PDU Router an.</li>\n<li><strong>Modulbezeichnungen:</strong> Abkürzungen durch Langbezeichnungen ersetzt (<code>IPDU Multiplexer</code>, <code>AUTOSAR COM</code>, <code>Diagnostic Communication Manager</code>, <code>AUTOSAR Tp</code>, <code>NM Module</code>).</li>\n<li><strong>Schnittstellenbeschriftungen:</strong> Verbindungslinien explizit mit Daten- und PDU-Typen typisiert (<code>Signals</code>, <code>I-PDU</code>, <code>I-PDU¹</code>, <code>N-PDU</code>, <code>L-PDU</code>).</li>\n</ul>"}]};
